messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>3D Treadmill Animation</title>
<style>
  * { margin: 0; padding: 0; box-sizing: border-box; }
  body {
    background: #0a0a1a;
    overflow: hidden;
    height: 100vh;
    width: 100vw;
  }
  canvas {
    display: block;
    width: 100%;
    height: 100%;
  }
</style>
</head>
<body>
<script type="module">
import * as THREE from './three.module.js';

// ─── Scene Setup ───
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x0a0a1a);
scene.fog = new THREE.Fog(0x0a0a1a, 20, 60);

const camera = new THREE.PerspectiveCamera(55, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(0, 1.5, 12);
camera.lookAt(0, 0.5, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true, alpha: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
document.body.appendChild(renderer.domElement);

// ─── Lighting ───
const ambientLight = new THREE.AmbientLight(0x444488, 0.5);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0xffffff, 0.8);
dirLight.position.set(5, 10, 8);
dirLight.castShadow = true;
scene.add(dirLight);

const fillLight = new THREE.DirectionalLight(0x8888cc, 0.3);
fillLight.position.set(-5, 6, -5);
scene.add(fillLight);

// ─── Treadmill / Ground ───
const groundGeo = new THREE.PlaneGeometry(60, 60, 2, 2);
const groundMat = new THREE.MeshStandardMaterial({
  color: 0x222233,
  roughness: 0.8,
  metalness: 0.1
});
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.position.y = -0.1;
ground.receiveShadow = true;
scene.add(ground);

// Treadmill belt visual
const beltGeo = new THREE.PlaneGeometry(12, 4, 1, 1);
const beltMat = new THREE.MeshStandardMaterial({
  color: 0x1a1a2e,
  roughness: 0.7,
  metalness: 0.3
});
const belt = new THREE.Mesh(beltGeo, beltMat);
belt.rotation.x = -Math.PI / 2;
belt.position.y = -0.05;
belt.position.z = 0;
scene.add(belt);

// Belt lines for motion effect
const beltLineGeo = new THREE.PlaneGeometry(12, 4, 1, 32);
const beltLineMat = new THREE.MeshBasicMaterial({
  color: 0x333344,
  transparent: true,
  opacity: 0.3
});
const beltLines = new THREE.Mesh(beltLineGeo, beltLineMat);
beltLines.rotation.x = -Math.PI / 2;
beltLines.position.y = -0.05;
beltLines.position.z = 0;
scene.add(beltLines);

// ─── Humanoid Figure ───
const figureGroup = new THREE.Group();
scene.add(figureGroup);

const skinColor = 0xccaa88;
const skinRoughness = 0.5;
const skinMetalness = 0.0;
const skinMat = new THREE.MeshStandardMaterial({
  color: skinColor,
  roughness: skinRoughness,
  metalness: skinMetalness,
  side: THREE.DoubleSide
});

const jointRadius = 0.08;
const limbRadius = 0.05;
const shinRadius = 0.04;

// ─── Create body parts ───
function createCylinder(x, y, z, radius, height, material, rotation = new THREE.Vector3(0, 0, 0)) {
  const geo = new THREE.CylinderGeometry(radius, radius, height, 12);
  const mesh = new THREE.Mesh(geo, material);
  mesh.position.set(x, y, z);
  mesh.rotation.copy(rotation);
  return mesh;
}

function createSphere(x, y, z, radius, material) {
  const geo = new THREE.SphereGeometry(radius, 12, 12);
  const mesh = new THREE.Mesh(geo, material);
  mesh.position.set(x, y, z);
  return mesh;
}

function createBox(x, y, z, width, height, depth, material) {
  const geo = new THREE.BoxGeometry(width, height, depth);
  const mesh = new THREE.Mesh(geo, material);
  mesh.position.set(x, y, z);
  return mesh;
}

// ─── Head ───
const headSphere = createSphere(0, 0.9, 0, 0.08, skinMat);
figureGroup.add(headSphere);

// ─── Neck ───
const neck = createCylinder(0, 0.82, 0, jointRadius, 0.06, skinMat);
figureGroup.add(neck);

// ─── Torso ───
const torso = createBox(0, 0.65, 0, 0.35, 0.35, 0.18, skinMat);
figureGroup.add(torso);

// ─── Left Arm ───
const leftArmGroup = new THREE.Group();
const leftUpperArm = createCylinder(0, -0.08, -0.14, limbRadius, 0.22, skinMat);
leftUpperArm.parent = leftArmGroup;
leftArmGroup.add(leftUpperArm);

const leftForearm = createCylinder(0, -0.08, -0.36, limbRadius * 0.85, 0.18, skinMat);
leftForearm.parent = leftArmGroup;
leftArmGroup.add(leftForearm);

const leftHand = createSphere(0, -0.08, -0.54, 0.035, skinMat);
leftHand.parent = leftArmGroup;
leftArmGroup.add(leftHand);

figureGroup.add(leftArmGroup);

// ─── Right Arm ───
const rightArmGroup = new THREE.Group();
const rightUpperArm = createCylinder(0, -0.08, 0.14, limbRadius, 0.22, skinMat);
rightUpperArm.parent = rightArmGroup;
rightArmGroup.add(rightUpperArm);

const rightForearm = createCylinder(0, -0.08, 0.36, limbRadius * 0.85, 0.18, skinMat);
rightForearm.parent = rightArmGroup;
rightArmGroup.add(rightForearm);

const rightHand = createSphere(0, -0.08, 0.54, 0.035, skinMat);
rightHand.parent = rightArmGroup;
rightArmGroup.add(rightHand);

figureGroup.add(rightArmGroup);

// ─── Left Leg ───
const leftLegGroup = new THREE.Group();
const leftThigh = createCylinder(0, 0.08, -0.14, limbRadius * 1.1, 0.38, skinMat);
leftThigh.parent = leftLegGroup;
leftLegGroup.add(leftThigh);

const leftShin = createCylinder(0, 0.08, 0.24, shinRadius, 0.32, skinMat);
leftShin.parent = leftLegGroup;
leftLegGroup.add(leftShin);

const leftFoot = createBox(0, 0.08, 0.56, 0.14, 0.08, 0.12, skinMat);
leftFoot.parent = leftLegGroup;
leftLegGroup.add(leftFoot);

figureGroup.add(leftLegGroup);

// ─── Right Leg ───
const rightLegGroup = new THREE.Group();
const rightThigh = createCylinder(0, 0.08, 0.14, limbRadius * 1.1, 0.38, skinMat);
rightThigh.parent = rightLegGroup;
rightLegGroup.add(rightThigh);

const rightShin = createCylinder(0, 0.08, -0.24, shinRadius, 0.32, skinMat);
rightShin.parent = rightLegGroup;
rightLegGroup.add(rightShin);

const rightFoot = createBox(0, 0.08, -0.56, 0.14, 0.08, 0.12, skinMat);
rightFoot.parent = rightLegGroup;
rightLegGroup.add(rightFoot);

figureGroup.add(rightLegGroup);

// ─── Animation State ───
const cycleLength = 10; // seconds
let elapsed = 0;
let phase = 0; // 0-1

// Phase durations
const STAND1 = 2;   // 0-2: stand still
const WALK = 3;     // 2-5: walk in place
const RUN = 3;      // 5-8: run in place
const STAND2 = 2;   // 8-10: stand still

const getPhaseDuration(phase) {
  if (phase < 0.2) return STAND1 / cycleLength;
  if (phase < 0.5) return WALK / cycleLength;
  if (phase < 0.8) return RUN / cycleLength;
  return STAND2 / cycleLength;
}

function getPhase() {
  if (phase < 0.2) return 'stand';
  if (phase < 0.5) return 'walk';
  if (phase < 0.8) return 'run';
  return 'stand';
}

function getPhaseProgress(phase) {
  if (phase < 0.2) return (phase - 0) / 0.2;
  if (phase < 0.5) return (phase - 0.2) / 0.3;
  if (phase < 0.8) return (phase - 0.5) / 0.3;
  return (phase - 0.8) / 0.2;
}

function getSpeed(phase) {
  if (phase < 0.2) return 0;
  if (phase < 0.5) return 1;
  if (phase < 0.8) return 1.8;
  return 0;
}

function getLean(phase) {
  if (phase < 0.2) return 0;
  if (phase < 0.5) return 0.04;
  if (phase < 0.8) return 0.1;
  return 0;
}

// ─── Joint Rotation Functions ───
// Returns angle offset for each limb based on phase
function getJointAngle(phase, part, side) {
  const t = getPhaseProgress(phase);
  const speed = getSpeed(phase);
  const lean = getLean(phase);
  const baseAngle = side === 'left' ? 0 : Math.PI;

  // Hip rotation (forward/back)
  let hipAngle = 0;
  if (side === 'left') {
    hipAngle = Math.sin(t * Math.PI * speed * 2) * 0.15 * speed;
  } else {
    hipAngle = Math.sin(t * Math.PI * speed * 2 + Math.PI) * 0.15 * speed;
  }

  // Shoulder rotation (forward/back)
  let shoulderAngle = 0;
  if (side === 'left') {
    shoulderAngle = Math.sin(t * Math.PI * speed * 2 + 1) * 0.12 * speed;
  } else {
    shoulderAngle = Math.sin(t * Math.PI * speed * 2 + Math.PI + 1) * 0.12 * speed;
  }

  // Elbow rotation
  let elbowAngle = 0;
  if (side === 'left') {
    elbowAngle = Math.sin(t * Math.PI * speed * 2 + 2) * 0.1 * speed;
  } else {
    elbowAngle = Math.sin(t * Math.PI * speed * 2 + Math.PI + 2) * 0.1 * speed;
  }

  // Knee rotation
  let kneeAngle = 0;
  if (side === 'left') {
    kneeAngle = Math.sin(t * Math.PI * speed * 2 + 3) * 0.2 * speed;
  } else {
    kneeAngle = Math.sin(t * Math.PI * speed * 2 + Math.PI + 3) * 0.2 * speed;
  }

  // Ankle rotation
  let ankleAngle = 0;
  if (side === 'left') {
    ankleAngle = Math.sin(t * Math.PI * speed * 2 + 4) * 0.15 * speed;
  } else {
    ankleAngle = Math.sin(t * Math.PI * speed * 2 + Math.PI + 4) * 0.15 * speed;
  }

  // Hip yaw (for running lean)
  let hipYaw = 0;
  if (phase >= 0.5 && phase < 0.8) {
    hipYaw = lean * 0.3 * Math.sin(t * Math.PI * speed * 2) * speed;
  }

  return { hipAngle, shoulderAngle, elbowAngle, kneeAngle, ankleAngle, hipYaw };
}

// ─── Animation Loop ───
function animate() {
  requestAnimationFrame(animate);

  // Update elapsed time
  if (!elapsed) elapsed = performance.now() / 1000;
  const now = performance.now() / 1000;
  elapsed = now % cycleLength;
  phase = elapsed / cycleLength;

  const speed = getSpeed(phase);
  const lean = getLean(phase);

  // ─── Apply lean to entire figure ───
  figureGroup.rotation.z = lean;

  // ─── Treadmill belt motion ───
  const beltSpeed = speed * 0.5;
  beltLines.rotation.z = (beltLines.rotation.z + beltSpeed * 0.1) % Math.PI;

  // ─── Left Arm ───
  const leftAngles = getJointAngle(phase, 'left');
  leftUpperArm.rotation.z = leftAngles.shoulderAngle;
  leftUpperArm.rotation.x = leftAngles.elbowAngle;
  leftForearm.rotation.z = leftAngles.kneeAngle;
  leftForearm.rotation.x = leftAngles.ankleAngle;

  // ─── Right Arm ───
  const rightAngles = getJointAngle(phase, 'right');
  rightUpperArm.rotation.z = rightAngles.shoulderAngle;
  rightUpperArm.rotation.x = rightAngles.elbowAngle;
  rightForearm.rotation.z = rightAngles.kneeAngle;
  rightForearm.rotation.x = rightAngles.ankleAngle;

  // ─── Left Leg ───
  const leftLegAngles = getJointAngle(phase, 'left');
  leftThigh.rotation.z = leftLegAngles.hipAngle;
  leftThigh.rotation.x = leftLegAngles.hipYaw;
  leftShin.rotation.z = leftLegAngles.kneeAngle;
  leftShin.rotation.x = leftLegAngles.ankleAngle;

  // ─── Right Leg ───
  const rightLegAngles = getJointAngle(phase, 'right');
  rightThigh.rotation.z = rightLegAngles.hipAngle;
  rightThigh.rotation.x = rightLegAngles.hipYaw;
  rightShin.rotation.z = rightLegAngles.kneeAngle;
  rightShin.rotation.x = rightLegAngles.ankleAngle;

  // ─── Camera subtle sway during movement ───
  const camSway = speed * 0.05;
  camera.position.x += camSway * Math.sin(phase * Math.PI * 10);
  camera.position.z += camSway * Math.cos(phase * Math.PI * 10);
  camera.lookAt(0, 0.5, 0);

  renderer.render(scene, camera);
}

// ─── Resize Handler ───
window.addEventListener('resize', () => {
  camera.aspect = window.innerWidth / window.innerHeight;
  camera.updateProjectionMatrix();
  renderer.setSize(window.innerWidth, window.innerHeight);
});

// ─── Start ───
animate();
</script>
</body>
</html>
```
